// Build-time loaders for the WEC dataset (generated by the wec_predictions
// pipeline). Server components in a static export read these JSON files from
// disk at build time — no runtime fetches. Never import this module from a
// "use client" component (it pulls in node:fs).

import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

import type {
  CalibrationSummary,
  ForwardEvalSeason,
  ProbabilitiesRound,
  RoundDetail,
  WecData,
} from "@/types/wec";

const DATA_DIR = join(process.cwd(), "public", "data");

function readJson<T>(...segments: string[]): T | null {
  const path = join(DATA_DIR, ...segments);
  if (!existsSync(path)) return null;
  try {
    return JSON.parse(readFileSync(path, "utf-8")) as T;
  } catch {
    return null;
  }
}

function pad2(n: number): string {
  return String(n).padStart(2, "0");
}

let cache: WecData | null = null;

export function getWecData(): WecData {
  if (cache) return cache;
  cache = readJson<WecData>("wec.json");
  if (!cache) throw new Error("wec.json missing — run the wec_predictions export first");
  return cache;
}

export function getRound(round: number): RoundDetail | null {
  return readJson<RoundDetail>("rounds", `round_${pad2(round)}.json`);
}

export function getProbabilities(round: number): ProbabilitiesRound | null {
  return readJson<ProbabilitiesRound>("probabilities", `round_${pad2(round)}.json`);
}

export function getCalibrationSummary(): CalibrationSummary | null {
  return readJson<CalibrationSummary>("calibration_summary.json");
}

/** Optional continuous-learning summary — returns null when absent (guarded). */
export function getForwardEvalSeason(): ForwardEvalSeason | null {
  return readJson<ForwardEvalSeason>("forward_eval", "season.json");
}

/**
 * Every round number that has a published detail file, ascending. Drives
 * generateStaticParams for /round/[round]. Includes the upcoming (unscored)
 * round, which the export publishes ahead of the event — so we scan the
 * rounds/ directory rather than trusting the completed-only calendar.
 */
export function allRoundNumbers(): number[] {
  const dir = join(DATA_DIR, "rounds");
  if (!existsSync(dir)) return [];
  const rounds = readdirSync(dir)
    .map((f) => /^round_(\d+)\.json$/.exec(f))
    .filter((m): m is RegExpExecArray => m !== null)
    .map((m) => parseInt(m[1], 10))
    .filter((n) => Number.isFinite(n));
  return Array.from(new Set(rounds)).sort((a, b) => a - b);
}

/** Every entry code across all classes' standings — drives /entry/[code]. */
export function allEntryCodes(): string[] {
  const data = getWecData();
  const codes = new Set<string>();
  for (const rows of Object.values(data.standings)) {
    for (const row of rows) codes.add(row.code);
  }
  return Array.from(codes);
}

const BASE_PATH = process.env.NEXT_PUBLIC_BASE_PATH || "";

/** basePath-aware asset URL for static export (brand, icons, …). */
export function asset(path: string): string {
  return `${BASE_PATH}${path.startsWith("/") ? path : `/${path}`}`;
}

// --------------------------------------------------------------------------- //
// Per-class points-progression series (for the standings projection chart).
//
// The export publishes a genuine per-round cumulative `pointsHistory` on every
// entry standing, so no reconstruction from finishing orders is needed — the
// curve endpoints match the published totals exactly. Entries that have not
// contested every round carry a shorter history; we left-pad honestly with the
// rounds they were actually scored on (their history is aligned to the END of
// the completed-rounds axis).
// --------------------------------------------------------------------------- //
export interface PointsProgression {
  /** Completed round numbers, e.g. [1,2,3,4]. */
  rounds: number[];
  /** class key → entry code → cumulative points aligned to `rounds`. */
  byClass: Record<string, Record<string, (number | null)[]>>;
}

export function getPointsProgression(): PointsProgression {
  const data = getWecData();
  const completed = data.calendar.filter((c) => c.completed).map((c) => c.round);
  const n = completed.length;

  const byClass: Record<string, Record<string, (number | null)[]>> = {};
  for (const [key, rows] of Object.entries(data.standings)) {
    const series: Record<string, (number | null)[]> = {};
    for (const row of rows) {
      const hist = Array.isArray(row.pointsHistory) ? row.pointsHistory : [];
      // Right-align: a shorter history means the entry joined mid-season, so
      // pad the leading rounds with null (chart skips those segments).
      const pad = Math.max(0, n - hist.length);
      series[row.code] = [
        ...Array<null>(pad).fill(null),
        ...hist.slice(Math.max(0, hist.length - n)),
      ];
    }
    byClass[key] = series;
  }

  return { rounds: completed, byClass };
}
